const TARGET_HOURS = 1;
const REMINDER_FIELD = 'reminder_1h';
const REMINDER_KEY = '1h';
const TOLERANCE_MINUTES = 10;

const now = new Date();
const targetMs = TARGET_HOURS * 60 * 60 * 1000;
const toleranceMs = TOLERANCE_MINUTES * 60 * 1000;
const tz = 'Europe/Moscow';

const outputs = [];

for (const item of $input.all()) {
  const appt = item.json || {};
  const dt = new Date(appt.date);
  if (Number.isNaN(dt.getTime())) continue;

  const reminderVal = String(appt[REMINDER_FIELD] ?? '').trim();
  if (reminderVal !== '') continue;

  const diffMs = dt.getTime() - now.getTime();
  if (Math.abs(diffMs - targetMs) > toleranceMs) continue;

  const dateFormatted = dt.toLocaleDateString('ru-RU', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    timeZone: tz,
  }) + ' в ' + dt.toLocaleTimeString('ru-RU', {
    hour: '2-digit',
    minute: '2-digit',
    timeZone: tz,
    hour12: false,
  });

  const clientName = String(appt.clientName || 'Клиент').trim() || 'Клиент';
  const richText = [
    '📅 Напоминание о записи',
    '',
    'Привет, ' + clientName + '!',
    'До вашей записи осталось ' + TARGET_HOURS + ' ч.',
    '',
    '🗓 Дата: ' + dateFormatted,
    '✂️ Услуга: ' + String(appt.service_name || ''),
    '👤 Мастер: ' + String(appt.master_name || ''),
    '',
    'Подтвердите, пожалуйста, визит:',
  ].join('\n');

  const smsText = [
    'Напоминание о записи',
    'До визита ' + TARGET_HOURS + ' ч.',
    'Дата: ' + dateFormatted,
    'Услуга: ' + String(appt.service_name || ''),
    'Мастер: ' + String(appt.master_name || ''),
  ].join('\n');

  const channelsByPriority = [
    {
      key: 'whatsapp',
      recipient: String(appt.wa_id || '').trim(),
      valid: String(appt.wa_id || '').trim() !== '',
    },
    {
      key: 'telegram',
      recipient: String(appt.tg_id || '').trim(),
      valid: Number(appt.tg_id || 0) > 0,
    },
    {
      key: 'max',
      recipient: String(appt.max_id || '').trim(),
      valid: String(appt.max_id || '').trim() !== '',
    },
    {
      key: 'sms',
      recipient: String(appt.phone || '').trim(),
      valid: String(appt.phone || '').trim() !== '' && String(appt.phone || '0') !== '0',
    },
  ];

  const selected = channelsByPriority.find((c) => c.valid);
  if (!selected) continue;

  outputs.push({
    json: {
      record_id: Number(appt.record_id),
      channel: selected.key,
      recipient: selected.recipient,
      tg_id: String(appt.tg_id || ''),
      rich_text: richText,
      sms_text: smsText,
      date_formatted: dateFormatted,
      reminder_key: REMINDER_KEY,
      debug_target_hours: TARGET_HOURS,
      debug_tolerance_minutes: TOLERANCE_MINUTES,
      debug_diff_minutes: Math.round(diffMs / 60000),
    },
  });
}

return outputs;

